function applyLang(lang){
 document.documentElement.lang=lang;
 document.documentElement.dir=lang==="ar"?"rtl":"ltr";
 document.body.classList.toggle("rtl",lang==="ar");
 document.querySelectorAll("[data-i18n]").forEach(el=>{
   const k=el.dataset.i18n;
   if(T[lang]?.[k]!==undefined) el.innerHTML=T[lang][k];
 });
 document.querySelectorAll("[data-i18n-placeholder]").forEach(el=>{
   const k=el.dataset.i18nPlaceholder;
   if(T[lang]?.[k]!==undefined) el.placeholder=T[lang][k];
 });
 localStorage.setItem("lang",lang);
}
const lang=localStorage.getItem("lang")||"en";
document.getElementById("language").value=lang;
applyLang(lang);

const savedScrollY=sessionStorage.getItem("languageReloadScrollY");
const savedDetailKey=sessionStorage.getItem("languageReloadDetailKey");
if(savedScrollY!==null || savedDetailKey){
 sessionStorage.removeItem("languageReloadScrollY");
 sessionStorage.removeItem("languageReloadDetailKey");
 requestAnimationFrame(()=>{
  if(savedScrollY!==null) window.scrollTo(0, Number(savedScrollY));
  if(savedDetailKey) openDetail(savedDetailKey);
 });
}

document.getElementById("language").addEventListener("change",e=>{
 applyLang(e.target.value);
 sessionStorage.setItem("languageReloadScrollY", String(window.scrollY));
 const modal=document.getElementById("modal");
 if(modal.classList.contains("open") && window.currentDetailKey){
  sessionStorage.setItem("languageReloadDetailKey", window.currentDetailKey);
 }
 window.location.reload();
});

// Theme selector: persists across visits.
(function(){const root=document.documentElement,light=document.getElementById("themeLight"),dark=document.getElementById("themeDark");function setTheme(t){root.setAttribute("data-theme",t);light.classList.toggle("active",t==="light");dark.classList.toggle("active",t==="dark");localStorage.setItem("theme",t)}const saved=localStorage.getItem("theme")||"light";setTheme(saved);light.addEventListener("click",()=>setTheme("light"));dark.addEventListener("click",()=>setTheme("dark"))})();
